const catalogue = [
  { sku: "RICE-5KG", kobo: 850000 },
  { sku: "OIL-1L", kobo: 240000 },
  { sku: "SALT-500G", kobo: 30000 },
];
const cart = [
  { sku: "OIL-1L", quantity: 2 },
  { sku: "SALT-500G", quantity: 3 },
  { sku: "SUGAR-1KG", quantity: 1 },
];

function cartTotal(catalogue, cart) {
  const bySku = new Map(catalogue.map((p) => [p.sku, p]));
  let total = 0;
  for (const line of cart) {
    const product = bySku.get(line.sku);
    if (product) total += product.kobo * line.quantity;
  }
  return total;
}

console.log(cartTotal(catalogue, cart));

