function bestSeller(sold) {
  const counts = new Map();
  for (const sku of sold) counts.set(sku, (counts.get(sku) ?? 0) + 1);
  let best = null;
  for (const entry of counts) {
    if (best === null || entry[1] > best[1]) best = entry;
  }
  return best;
}

