function uniqueEmails(emails) {
  const seen = new Set();
  const result = [];
  for (const email of emails) {
    const key = email.trim().toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(email);
  }
  return result;
}

console.log(uniqueEmails(["ada@shop.ng", " ADA@shop.ng", "bola@shop.ng", "Bola@Shop.ng "]));

