class MiniTable {
  constructor(size = 4) {
    this.buckets = Array.from({ length: size }, () => []);
  }
  bucketFor(key) {
    let h = 0;
    for (const ch of key) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
    return this.buckets[h % this.buckets.length];
  }
  set(key, value) {
    const bucket = this.bucketFor(key);
    for (const entry of bucket) {
      if (entry[0] === key) {
        entry[1] = value;
        return this;
      }
    }
    bucket.push([key, value]);
    return this;
  }
  get(key) {
    for (const [k, v] of this.bucketFor(key)) {
      if (k === key) return v;
    }
    return undefined;
  }
}

const phones = new MiniTable();
phones.set("Ada", "0803 000 0001").set("Bola", "0805 000 0002").set("Ada", "0803 999 9999");
console.log(phones.get("Ada"), phones.get("Bola"), phones.get("Chidi"));
